import { mount, signal, delegate } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';
import { TokenSearchField, readTokenSearchField, placeTokenSearchCaret, type TokenSearchFieldValue, type TokenSearchToken } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';
import './search.css';
export function mountSearch(root: HTMLElement, app: {
 parse(value: TokenSearchFieldValue): TokenSearchFieldValue;
 search(value: TokenSearchFieldValue): void;
 editToken(token: TokenSearchToken, draft: string): TokenSearchToken | null;
}) {
 const model = signal<TokenSearchFieldValue>({ query: '', tokens: [] });
 const editing = signal<number | null>(null);
 let draft = '';
 const editor = () => root.querySelector<HTMLElement>('[data-search-editor]')!;
 const announce = (message: string) => { const status = root.querySelector('[data-search-status]'); if (status) status.textContent = message; };
 const read = () => readTokenSearchField(editor(), model.value.tokens);
 const replace = (next: TokenSearchFieldValue, caret: number, message: string) => {
  model.value = next;
  queueMicrotask(() => { placeTokenSearchCaret(editor(), caret); announce(message); app.search(next); });
 };
 const stopMount = mount(root, () => <section class="search kui-layout kui-section-stack">
  <div class="kui-surface-body kui-section-stack">
   <TokenSearchField id="workspace-search" label="Search workspace with filters" placeholder="Search or enter a filter" query={model.value.query} tokens={model.value.tokens} editAction="edit-filter" removeAction="remove-filter" clearAction="clear-search" clearLabel="Clear search text and all filters" editorAttributes={{ 'data-search-editor': 'true' }} />
   <div class="kui-control-cluster"><button type="button" data-action="apply-search">Apply search and parse filters</button></div>
   {editing.value !== null && <div class="kui-section-stack"><label for="filter-draft">Edit filter</label><input id="filter-draft" value={draft} /><div class="kui-control-cluster"><button type="button" data-action="save-filter">Save filter</button><button type="button" data-action="cancel-filter">Cancel</button></div></div>}
   <p role="status" aria-live="polite" data-search-status=""></p>
  </div>
 </section>);
 const tokenIndex = (element: Element, action: string) => Array.from(root.querySelectorAll('[data-action="' + action + '"]')).indexOf(element);
 const stopInput = delegate(root, 'input', '[data-search-editor]', () => { app.search(read()); });
 const stopDraft = delegate(root, 'input', '#filter-draft', (_e, element) => { draft = (element as HTMLInputElement).value; });
 const stopActions = delegateActions(root, 'click', {
  'apply-search': () => { const next = app.parse(read()); replace(next, next.query.length, 'Search filters applied'); },
  'clear-search': () => { editor().textContent = ''; editing.value = null; replace({ query: '', tokens: [] }, 0, 'Search cleared'); },
  'remove-filter': (_e, element) => { const current = read(); const index = tokenIndex(element, 'remove-filter'); if (index < 0) return; const removed = current.tokens[index]; replace({ query: current.query, tokens: current.tokens.filter((_t, i) => i !== index) }, removed?.offset ?? current.query.length, 'Filter removed'); },
  'edit-filter': (_e, element) => { const current = read(); const index = tokenIndex(element, 'edit-filter'); if (!current.tokens[index]) return; model.value = current; draft = current.tokens[index].value; editing.value = index; queueMicrotask(() => root.querySelector<HTMLInputElement>('#filter-draft')?.focus()); },
  'save-filter': () => { const index = editing.value; if (index === null) return; const current = read(); const token = current.tokens[index]; if (!token) return; const next = app.editToken(token, draft); if (!next) { announce('Invalid filter. Update the value and try again.'); return; } const tokens = [...current.tokens]; tokens[index] = { ...next, offset: token.offset }; editing.value = null; replace({ query: current.query, tokens }, token.offset ?? current.query.length, 'Filter updated'); },
  'cancel-filter': () => { editing.value = null; queueMicrotask(() => { placeTokenSearchCaret(editor()); announce('Filter edit cancelled'); }); }
 });
 const stopKeys = delegate(root, 'keydown', '#filter-draft', (event) => { if ((event as KeyboardEvent).key === 'Escape') { event.preventDefault(); editing.value = null; queueMicrotask(() => placeTokenSearchCaret(editor())); } });
 return () => { stopKeys(); stopActions(); stopDraft(); stopInput(); stopMount(); };
}

